('admin.inventory.transfers.title', 'zh-CN', '调拨单', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
('admin.inventory.transfers.title', 'en-US', 'Stock transfers', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
('admin.inventory.transfers.hint', 'zh-CN', '调拨是仓库之间的移库：建单时定两个仓，出货扣源仓、签收加目标仓。出货与签收都必须上传凭证附件 —— 一张没有凭证的移库事后无法证明货是谁交出去的、谁签收的。', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
('admin.inventory.transfers.hint', 'en-US', 'A transfer moves stock between warehouses: pick both warehouses when creating it, shipping deducts the source, receiving adds to the target. Both shipping and receiving require voucher attachments — without them you cannot prove later who handed the goods over and who signed for them.', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
('admin.inventory.transfers.sub', 'zh-CN', '调拨用的是可售数量（被订单预占的部分不能调拨）。未认领的货也可以调拨 —— 它同样是仓库里的一批货。', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
('admin.inventory.transfers.sub', 'en-US', 'Transfers use available quantity (what unshipped orders reserved is off limits). Unclaimed stock can be transferred too — it is still goods sitting in a warehouse.', 200, 'inventory', 'internal/templates/admin/inventory/inventory_transfers.html', 1, now(), now()),
